import sys

def find_longest_palindrome(s):
    n = len(s)
    max_length = 0
    best_palindrome = ""

    # Check all possible palindromes
    for i in range(n):
        for j in range(i, n):
            candidate = s[i:j+1]
            if candidate == candidate[::-1]:
                if j - i + 1 > max_length:
                    max_length = j - i + 1
                    best_palindrome = candidate

    return best_palindrome

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    t = int(data[0])
    index = 1
    results = []

    for _ in range(t):
        s = data[index]
        index += 1
        result = find_longest_palindrome(s)
        results.append(result)

    for result in results:
        print(result)

if __name__ == "__main__":
    main()

def longest_palindrome_with_prefix_suffix(s):
    n = len(s)
    dp = [[False] * n for _ in range(n)]

    # All substrings of length 1 are palindromes
    for i in range(n):
        dp[i][i] = True

    # Check for substrings of length 2
    for i in range(n - 1):
        if s[i] == s[i + 1]:
            dp[i][i + 1] = True

    # Check for substrings of length greater than 2
    for length in range(3, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j] and dp[i + 1][j - 1]:
                dp[i][j] = True

    # Find the longest palindromic substring that can be split into prefix and suffix
    max_length = 0
    result = ""

    for i in range(n):
        for j in range(i, n):
            if dp[i][j]:
                prefix = s[:i]
                suffix = s[j+1:]
                if s[i:j+1].startswith(prefix) and s[i:j+1].endswith(suffix):
                    if j - i + 1 > max_length:
                        max_length = j - i + 1
                        result = s[i:j+1]

    return result

